CREATE TABLE taxonomy_previews(token TEXT PRIMARY KEY,actor TEXT NOT NULL,taxonomy_revision INTEGER NOT NULL,catalog_revision INTEGER NOT NULL,active_version TEXT NOT NULL,operation_json TEXT NOT NULL,candidate_json TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE taxonomy_guards(token TEXT PRIMARY KEY,valid INTEGER NOT NULL CHECK(valid=1));
CREATE TRIGGER taxonomy_changed AFTER UPDATE ON taxonomy_state BEGIN UPDATE recognition_state SET catalog_revision=catalog_revision+1 WHERE id=1; END;
CREATE TRIGGER recognition_version_insert AFTER INSERT ON recognition_versions BEGIN UPDATE recognition_state SET catalog_revision=catalog_revision+1 WHERE id=1; END;
CREATE TRIGGER recognition_version_delete AFTER DELETE ON recognition_versions BEGIN UPDATE recognition_state SET catalog_revision=catalog_revision+1 WHERE id=1; END;
CREATE TABLE taxonomy_changes(revision INTEGER PRIMARY KEY,actor TEXT NOT NULL,operation_json TEXT NOT NULL,state_json TEXT NOT NULL,created_at TEXT NOT NULL);
